     5  const COLLATOR_OPTIONS: Intl.CollatorOptions = {usage: 'sort', sensitivity: 'base'};
     6
     7  let collator = new Intl.Collator(CONST.LOCALES.DEFAULT, COLLATOR_OPTIONS);
     8
     9  Onyx.connect({
    10      key: ONYXKEYS.NVP_PREFERRED_LOCALE,
    11      callback: (locale) => {
    12          collator = new Intl.Collator(locale ?? CONST.LOCALES.DEFAULT, COLLATOR_OPTIONS);
    13      },
    14  });
    15
    16  /**
    17   * This is a wrapper around the localeCompare function that uses the preferred locale from the user's settings.
    18   *
    19   * It re-uses Intl.Collator with static options for performance reasons. See https://github.com/facebook/hermes/issues/867 for more details.
    20   * @param a
    21   * @param b
    22   * @returns -1 if a < b, 1 if a > b, 0 if a === b
    23   */
    24  function localeCompare(a: string, b: string) {
    25      return collator.compare(a, b);
    26  }
    27
    28  export default localeCompare;

